            {"label": "Delivery body + policy owner", "value": "Trust E&F + rating advisers; Valuation Office Agency + LB Hackney + City of London Corporation + DLUHC + DHSC"},
            {"label": "Evaluation evidence", "value": "VOA 2023 revaluation list disclosure; HMT business-rates-review final report 2021; trust ARA"},
