            {"label": "Transport (business + patient) 2024-25", "value": "£1.809M"},
            {"label": "Trust scale", "value": "Medway Maritime Hospital (Gillingham) + outpatient clinic footprint across Medway Towns; c. 4,500 WTE; c. 425,000 catchment"},
            {"label": "Kent and Medway ICS", "value": "K&M ICS group with Dartford & Gravesham, East Kent Hospitals, Maidstone & Tunbridge Wells — cross-trust pathway reconfiguration drives inter-trust travel"},
            {"label": "NEPTS commissioning", "value": "Kent and Medway ICS lead-commissioner NEPTS contract; eligibility per NHSE 2021 criteria"},
            {"label": "Composition", "value": "Business mileage (AfC S17 + AMAP 45p/25p frozen since 2011) + pool-fleet IFRS 16 leases + NEPTS pass-through + patient travel reimbursements"},
            {"label": "Industrial action 2023-24 effect", "value": "44 days junior-doctor + 10 days consultant strikes drove cancellation rebooking + agency travel claims"},
            {"label": "April 2025 NIC + fuel CPI", "value": "Indirect via NEPTS contractor pass-through + diesel CPI feed forward unit-cost pressure"},
            {"label": "CQC special-measures legacy", "value": "Medway exited CQC special measures 2017 after extended quality-improvement programme; sustained inter-trust mentoring travel feeds business mileage"},
            {"label": "Funding trajectory", "value": "2021-22 c. £1.5M → 2023-24 c. £1.7M → 2024-25 £1.809M — fuel CPI + NEPTS contract uplift + activity recovery"},
